/**
 * @distilled.cloud/dokploy -- Dokploy API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from the OpenAPI document mirrored at
 * `specs/spec-mirror-dokploy/specs/openapi.json`. Everything else in this
 * folder is hand-written.
 *
 * One module per Dokploy router (`application`, `compose`, `project`,
 * `server`, ...). Dokploy is self-hosted; point the credentials at your
 * instance.
 *
 * @example
 * ```ts
 * import * as Dokploy from "@distilled.cloud/dokploy";
 *
 * yield* Dokploy.application.deployApplication({ applicationId: "<application id>" });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { DokployProtocol, type DokployOpError, type DokployOpContext } from "./protocol.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
